14	use Illuminate\Auth\Access\AuthorizationException;
15	use Illuminate\Contracts\Pagination\LengthAwarePaginator;
16	use Illuminate\Support\Collection;
17	
18	/**
19	 * Story 2-1 — central service for the Event domain.
20	 *
21	 * Phase 1 surface in this story: createDraft only. Subsequent stories
22	 * (2-2, 2-3a, 2-3b, 2-5, 2-6) extend this service with updateMetadata,
23	 * transition, publish (wrapper), cancel, suspend, reactivate.
24	 */
25	class EventService
26	{
27	    public function __construct(
28	        private readonly EventAuthorizationService $authz,
29	        private readonly EventReadService $reader,
30	        private readonly EventStateMachineService $stateMachine,
31	        private readonly EventModerationService $moderation,
32	        private readonly EventLifecycleService $lifecycle,
33	        private readonly EventMetadataService $metadata,
34	        private readonly EventLandingService $landing,
35	        private readonly PublicRegistrationService $publicRegistration,
36	        private readonly PublicLandingService $publicLanding,
37	    ) {}
38	
39	    public function getById(int $id): Event
40	    {
41	        return $this->reader->getById($id);
42	    }
43	
44	    /** @param array{search?: string|null, date_from?: string|null, date_to?: string|null} $filters */
45	    public function getPaginatedByTab(string $tab, int $perPage = 25, array $filters = []): LengthAwarePaginator
46	    {
47	        return $this->reader->getPaginatedByTab($tab, $perPage, $filters);
48	    }
49	
50	    /** @return Collection<int, Event> */
51	    public function getDashboardEventsForTeam(Team $team, int $limit = 5): Collection
52	    {
53	        return $this->reader->getDashboardEventsForTeam($team, $limit);
54	    }
55	
56	    public function countEventsForTeam(Team $team): int
57	    {
58	        return $this->reader->countEventsForTeam($team);
59	    }
60	
61	    public function countUpcomingEventsForTeam(Team $team): int
62	    {
63	        return $this->reader->countUpcomingEventsForTeam($team);
64	    }
65	
66	    /**
67	     * Delegates to EventAuthorizationService::authorizeView.
68	     * Kept as a public method so EventController::show() and the edit flow
69	     * can call it without knowing the authz service directly.
70	     *
71	     * @throws AuthorizationException
72	     */
73	    public function authorizeViewAccess(Event $event, User $actor): void
74	    {
75	        $this->authz->authorizeView($event, $actor);
76	    }
77	
78	    /**
79	     * List-access guard: actor may list events in their current team.
80	     *
81	     * Delegates to EventAuthorizationService::authorizeViewAny, which preserves
82	     * the current EventPolicy::viewAny behavior (events.view.global or events.view.team).
83	     *
84	     * @throws AuthorizationException
85	     */
86	    public function authorizeListAccess(User $actor): void
87	    {
88	        $team = $actor->currentTeam;
89	
90	        if ($team === null) {
91	            throw new AuthorizationException('A team context is required to list events.');
92	        }
93	
94	        $this->authz->authorizeViewAny($team, $actor);
95	    }
96	
97	    /**
98	     * Combined edit-form guard: view capability + update capability + state check.
99	     * The state check (DRAFT + not cancelled) is NOT a capability — it stays here.
100	     *
101	     * @throws AuthorizationException
102	     * @throws EventStateLocked
103	     */
104	    public function authorizeEditFormAccess(Event $event, User $actor): void
105	    {
106	        $this->authz->authorizeView($event, $actor);
107	        $this->metadata->authorizeEventUpdate($event->team, $actor);
108	
109	        if ($event->state !== EventState::DRAFT || $event->cancelled_at !== null) {
110	            throw EventStateLocked::for($event);
111	        }
112	    }
113	
114	    /**
115	     * Landing/form-config guard: view + update capability, allows DRAFT|PUBLISHED.
116	     *
117	     * LandingSetup, LandingPreview, and RegistrationFormConfig surfaces are
118	     * writable in both DRAFT and PUBLISHED states, unlike the stricter
119	     * authorizeEditFormAccess which only allows DRAFT.
120	     *
121	     * @throws AuthorizationException
122	     */
123	    public function authorizeLandingFormAccess(Event $event, User $actor): void
124	    {
125	        $this->authz->authorizeView($event, $actor);
126	        $this->metadata->authorizeEventUpdate($event->team, $actor);
127	    }
128	
129	    /**
130	     * Prepare-checklist guard: view + update capability.
131	     *
132	     * The prepare checklist is accessible in PUBLISHED state (it's the gate
133	     * to transition PUBLISHED→PREPARING). State validation is handled inside
134	     * EventStateMachineService during the actual prepare() call, not at the
135	     * component guard level.
136	     *
137	     * @throws AuthorizationException
138	     */
139	    public function authorizePrepareAccess(Event $event, User $actor): void
140	    {
141	        $this->authz->authorizeView($event, $actor);
142	        $this->metadata->authorizeEventUpdate($event->team, $actor);
143	    }
144	
145	    /**
146	     * @param  array<string, mixed>  $metadata
147	     */
148	    public function createDraft(Team $team, User $actor, array $metadata): Event
149	    {
150	        return $this->metadata->createDraft($team, $actor, $metadata);
151	    }
152	
153	    /**
154	     * Story 2-3b — Publish (DRAFT → PUBLISHED) with plan-gate triple-lock.
155	     *
156	     * Layer 3 of the triple-lock (FR80 / AR17): the service MUST re-check the
157	     * EVENT_PUBLISH entitlement even after the route capability + UI gate.
158	     * If the event team's plan does not grant PUBLISH, throws
159	     * PlanGateFailed (HTTP 402, JKM-EVT-1003).
160	     *
161	     * Idempotency comes for free from `transition()`'s same-state no-op.
162	     * Cancellation blocking comes from `transition()`'s cancelled_at re-read.
163	     */
164	    public function publish(Event $event, User $actor): Event
165	    {
166	        return $this->lifecycle->publish($event, $actor);
167	    }
168	
169	    /** @return array{allowed: bool, reason: string|null} */
170	    public function publishReadiness(Event $event, ?User $actor): array
171	    {
172	        return $this->lifecycle->publishReadiness($event, $actor);
173	    }
174	
175	    /** @param  array<string, mixed>  $payload */
176	    public function upsertLandingSetup(Event $event, User $actor, array $payload): LandingPage
177	    {
178	        return $this->landing->upsertLandingSetup($event, $actor, $payload);
179	    }
180	
181	    /** @param  array<string, mixed>  $payload */
182	    public function upsertRegistrationFormConfig(Event $event, User $actor, array $payload): LandingPage
183	    {
184	        return $this->landing->upsertRegistrationFormConfig($event, $actor, $payload);
185	    }
186	    /** @param array<string, mixed> $payload */
187	    public function submitPublicRegistration(Event $event, array $payload, ?string $ipAddress): array
188	    {
189	        return $this->publicRegistration->submitPublicRegistration($event, $payload, $ipAddress);
190	    }
191	
192	    /**
193	     * Story 4-17 — Resolve an Event by UUID for the delivery-logs surface.
194	     *
195	     * TeamScope bypass category: Authorization resolution — the route uses a plain
196	     * string parameter so TeamScope does not kill cross-team requests with 404 before
197	     * authorization runs. The event is found, then authorizeView enforces the team
198	     * boundary (403 for non-members, 200 for entitled members, bypass for SA).
199	     *
200	     * @throws \Symfony\Component\HttpKernel\Exception\HttpException 404 if no event with this UUID, 403 if not authorized.

